function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

var FONT_PAIRS=[
 {name:'经典衬线 + 无衬线', heading:'Georgia, serif', body:'Helvetica, Arial, sans-serif', note:'稳重耐读，适合长文与博客'},
 {name:'高对比衬线', heading:'Playfair Display, Georgia, serif', body:'Source Sans Pro, sans-serif', note:'编辑感强，适合杂志风'},
 {name:'几何无衬线统一', heading:'Inter, system-ui, sans-serif', body:'Inter, system-ui, sans-serif', note:'现代中性，适合产品界面'},
 {name:'厚重衬线 + 开放无衬线', heading:'Merriweather, serif', body:'Open Sans, sans-serif', note:'可读性优先，屏幕友好'},
 {name:'技术感无衬线', heading:'Space Grotesk, sans-serif', body:'IBM Plex Sans, sans-serif', note:'开发者文档、科技品牌'},
 {name:'柔和衬线', heading:'Lora, serif', body:'Muli, Helvetica, sans-serif', note:'温暖亲切，适合故事性内容'}
];
function fontPair(opts){
  opts=opts||{}; var seed=opts.seed!=null?opts.seed:1; var r=rngFactory(seed);
  var i=Math.floor(r()*FONT_PAIRS.length);
  var p=FONT_PAIRS[i];
  return {name:p.name, heading:p.heading, body:p.body, note:p.note, index:i};
}
function fontPairCss(p){
  return '--font-heading: '+p.heading+';\n--font-body: '+p.body+';';
}

var EXPORTS={fontPair:fontPair,fontPairCss:fontPairCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FontPairForgePure = EXPORTS; }
